key_functionalities.mermaid_diagram:
flowchart TD
    START([Start: Concurrent Change Detection\nLocked records now held for update])

    ACCT_CHECK[Compare Locked Account Record\nagainst Original Fetched Values]

    ACCT_STATUS{Active Status\nMatches?}
    ACCT_BAL{Current Balance\nMatches?}
    ACCT_CRED{Credit Limit\nMatches?}
    ACCT_CASH{Cash Credit Limit\nMatches?}
    ACCT_CYC_CR{Current Cycle\nCredit Matches?}
    ACCT_CYC_DB{Current Cycle\nDebit Matches?}
    ACCT_OPEN{Account Open Date\nYear, Month, Day\nAll Match?}
    ACCT_EXP{Account Expiry Date\nYear, Month, Day\nAll Match?}
    ACCT_REIS{Account Reissue Date\nYear, Month, Day\nAll Match?}
    ACCT_GRP{Group ID\nMatches?}

    CUST_CHECK[Compare Locked Customer Record\nagainst Original Fetched Values]

    CUST_FNAME{First Name\nMatches?}
    CUST_MNAME{Middle Name\nMatches?}
    CUST_LNAME{Last Name\nMatches?}
    CUST_ADDR1{Address Line 1\nMatches?}
    CUST_ADDR2{Address Line 2\nMatches?}
    CUST_CITY{City\nMatches?}
    CUST_STATE{State Code\nMatches?}
    CUST_COUNTRY{Country Code\nMatches?}
    CUST_ZIP{Zip Code\nMatches?}
    CUST_PH1{Primary Phone\nNumber Matches?}
    CUST_PH2{Secondary Phone\nNumber Matches?}
    CUST_SSN{SSN\nMatches?}
    CUST_GOVT{Govt Issued ID\nMatches?}
    CUST_DOB{Date of Birth\nYear, Month, Day\nAll Match?}
    CUST_EFT{EFT Account ID\nMatches?}
    CUST_PRI{Primary Card\nHolder Indicator\nMatches?}
    CUST_FICO{FICO Score\nMatches?}

    CHANGED([Record Changed by Another User\nStop Update - Refresh screen\nwith latest data and notify user])
    SAFE([No Concurrent Changes Detected\nSafe to Proceed with Update])

    START --> ACCT_CHECK
    ACCT_CHECK --> ACCT_STATUS
    ACCT_STATUS -->|No - Mismatch| CHANGED
    ACCT_STATUS -->|Yes| ACCT_BAL
    ACCT_BAL -->|No - Mismatch| CHANGED
    ACCT_BAL -->|Yes| ACCT_CRED
    ACCT_CRED -->|No - Mismatch| CHANGED
    ACCT_CRED -->|Yes| ACCT_CASH
    ACCT_CASH -->|No - Mismatch| CHANGED
    ACCT_CASH -->|Yes| ACCT_CYC_CR
    ACCT_CYC_CR -->|No - Mismatch| CHANGED
    ACCT_CYC_CR -->|Yes| ACCT_CYC_DB
    ACCT_CYC_DB -->|No - Mismatch| CHANGED
    ACCT_CYC_DB -->|Yes| ACCT_OPEN
    ACCT_OPEN -->|No - Mismatch| CHANGED
    ACCT_OPEN -->|Yes| ACCT_EXP
    ACCT_EXP -->|No - Mismatch| CHANGED
    ACCT_EXP -->|Yes| ACCT_REIS
    ACCT_REIS -->|No - Mismatch| CHANGED
    ACCT_REIS -->|Yes| ACCT_GRP
    ACCT_GRP -->|No - Mismatch| CHANGED
    ACCT_GRP -->|Yes - All Account Fields Match| CUST_CHECK
    CUST_CHECK --> CUST_FNAME
    CUST_FNAME -->|No - Mismatch| CHANGED
    CUST_FNAME -->|Yes| CUST_MNAME
    CUST_MNAME -->|No - Mismatch| CHANGED
    CUST_MNAME -->|Yes| CUST_LNAME
    CUST_LNAME -->|No - Mismatch| CHANGED
    CUST_LNAME -->|Yes| CUST_ADDR1
    CUST_ADDR1 -->|No - Mismatch| CHANGED
    CUST_ADDR1 -->|Yes| CUST_ADDR2
    CUST_ADDR2 -->|No - Mismatch| CHANGED
    CUST_ADDR2 -->|Yes| CUST_CITY
    CUST_CITY -->|No - Mismatch| CHANGED
    CUST_CITY -->|Yes| CUST_STATE
    CUST_STATE -->|No - Mismatch| CHANGED
    CUST_STATE -->|Yes| CUST_COUNTRY
    CUST_COUNTRY -->|No - Mismatch| CHANGED
    CUST_COUNTRY -->|Yes| CUST_ZIP
    CUST_ZIP -->|No - Mismatch| CHANGED
    CUST_ZIP -->|Yes| CUST_PH1
    CUST_PH1 -->|No - Mismatch| CHANGED
    CUST_PH1 -->|Yes| CUST_PH2
    CUST_PH2 -->|No - Mismatch| CHANGED
    CUST_PH2 -->|Yes| CUST_SSN
    CUST_SSN -->|No - Mismatch| CHANGED
    CUST_SSN -->|Yes| CUST_GOVT
    CUST_GOVT -->|No - Mismatch| CHANGED
    CUST_GOVT -->|Yes| CUST_DOB
    CUST_DOB -->|No - Mismatch| CHANGED
    CUST_DOB -->|Yes| CUST_EFT
    CUST_EFT -->|No - Mismatch| CHANGED
    CUST_EFT -->|Yes| CUST_PRI
    CUST_PRI -->|No - Mismatch| CHANGED
    CUST_PRI -->|Yes| CUST_FICO
    CUST_FICO -->|No - Mismatch| CHANGED
    CUST_FICO -->|Yes - All Customer Fields Match| SAFE
